program='''def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    from collections import Counter
    bg = Counter(v for row in a for v in row).most_common(1)[0][0]
    seeds = [v for v in Counter(v for row in a for v in row) if v != bg]

    def runs(vals):
        out = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            out.append((i, j - 1, color))
            i = j
        return out

    # Edge runs are paired on opposite edges; their within-run offsets correspond.
    edges = {
        'top': runs(a[0]),
        'bottom': runs(a[h - 1]),
        'left': runs([a[r][0] for r in range(h)]),
        'right': runs([a[r][w - 1] for r in range(h)]),
    }
    pairs = []
    for first, second, orient in [('top', 'bottom', 'H'), ('left', 'right', 'V')]:
        for x in edges[first]:
            for y in edges[second]:
                if x[2] == y[2]:
                    pairs.append((x, y, first, second, orient))
    if not pairs:
        return a
    edge_colors = {x[2] for x in sum((edges[k] for k in edges), [])}
    seed_color = next((v for v in seeds if v not in edge_colors), None)
    if seed_color is None:
        return a
    marks = [(r, c) for r in range(h) for c in range(w) if a[r][c] == seed_color]

    best = None
    best_score = 0
    for seg1, seg2, side1, side2, orient in pairs:
        start1, end1, _ = seg1
        start2, end2, _ = seg2
        count1 = sum(start1 <= (r if orient == 'V' else c) <= end1 for r, c in marks)
        count2 = sum(start2 <= (r if orient == 'V' else c) <= end2 for r, c in marks)
        if max(count1, count2) > best_score:
            best_score = max(count1, count2)
            if count1 > count2:
                best = (seg1, seg2, side1, side2, orient, side1, start1, start2)
            else:
                best = (seg2, seg1, side2, side1, orient, side2, start2, start1)
    if best is None:
        return a
    src_seg, dst_seg, src_side, dst_side, orient, _, src_start, dst_start = best
    src_end = src_seg[1]
    dst_end = dst_seg[1]
    offsets = set()
    selected = []
    for r, c in marks:
        pos = r if orient == 'V' else c
        if src_start <= pos <= src_end:
            off = pos - src_start
            if dst_start + off <= dst_end:
                offsets.add(off)
                selected.append((r, c))
    if not selected:
        return a
    for r, c in selected:
        # Extend each marker only toward its own edge run.
        a[r][c] = 4
        if src_side == 'left':
            for cc in range(1, c): a[r][cc] = seed_color
        elif src_side == 'right':
            for cc in range(c + 1, w - 1): a[r][cc] = seed_color
        elif src_side == 'top':
            for rr in range(1, r): a[rr][c] = seed_color
        elif src_side == 'bottom':
            for rr in range(r + 1, h - 1): a[rr][c] = seed_color
    # The matching edge run carries the same offsets across the grid.
    for off in offsets:
        pos = dst_start + off
        if dst_side in ('left', 'right'):
            c_range = range(1, w) if dst_side == 'left' else range(0, w - 1)
            for cc in c_range:
                a[pos][cc] = seed_color
        else:
            # Do not overwrite either horizontal edge row.
            for rr in range(1, h - 1):
                a[rr][pos] = seed_color
    # Reapply the marker color 4 after any projected lines.
    for r, c in selected:
        a[r][c] = 4
    return a
'''
